import { useState } from 'react';
import { useStore } from './store';
import { shallow } from 'zustand/shallow';
import { Play, X, CheckCircle, XCircle, GitBranch, Share2 } from 'lucide-react';

const selector = (s) => ({ nodes: s.nodes, edges: s.edges });

/* ── Result Modal ── */
const ResultModal = ({ result, error, onClose }) => {
  if (!result && !error) return null;

  const isDAG  = result?.is_dag;
  const accent = error ? '#f87171' : isDAG ? '#34d399' : '#fb923c';

  return (
    <div
      onClick={onClose}
      style={{
        position: 'fixed', inset: 0,
        background: 'rgba(0,0,0,0.65)',
        backdropFilter: 'blur(4px)',
        display: 'flex', alignItems: 'center', justifyContent: 'center',
        zIndex: 9999,
        fontFamily: "'Inter', system-ui, sans-serif",
      }}
    >
      <div
        onClick={e => e.stopPropagation()}
        style={{
          background: '#111118',
          border: `1px solid ${accent}44`,
          borderTop: `3px solid ${accent}`,
          borderRadius: 14,
          width: 360,
          boxShadow: `0 8px 40px #00000090, 0 0 0 1px ${accent}22`,
          overflow: 'hidden',
          animation: 'modalIn 0.18s ease',
        }}
      >
        {/* Header */}
        <div style={{
          display: 'flex', alignItems: 'center', justifyContent: 'space-between',
          padding: '14px 16px 12px',
          borderBottom: '1px solid #1e1e2a',
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            {error
              ? <XCircle size={16} color="#f87171" />
              : isDAG
                ? <CheckCircle size={16} color="#34d399" />
                : <XCircle size={16} color="#fb923c" />
            }
            <span style={{ color: '#e8e8f0', fontWeight: 700, fontSize: 14 }}>
              Pipeline Analysis
            </span>
          </div>
          <button
            onClick={onClose}
            style={{
              background: 'transparent', border: 'none',
              color: '#55556a', cursor: 'pointer',
              display: 'flex', alignItems: 'center', padding: 4, borderRadius: 6,
            }}
            onMouseEnter={e => { e.currentTarget.style.color = '#e8e8f0'; e.currentTarget.style.background = '#1e1e2a'; }}
            onMouseLeave={e => { e.currentTarget.style.color = '#55556a'; e.currentTarget.style.background = 'transparent'; }}
          >
            <X size={14} />
          </button>
        </div>

        {/* Body */}
        <div style={{ padding: '16px 18px' }}>
          {error ? (
            <div>
              <p style={{ color: '#f87171', fontSize: 13, lineHeight: 1.6, margin: 0 }}>
                {error}
              </p>
              <p style={{ color: '#55556a', fontSize: 11, marginTop: 10, lineHeight: 1.5 }}>
                Make sure the backend is running:<br />
                <code style={{ color: '#8888a8', background: '#0a0a0f', padding: '2px 6px', borderRadius: 4, fontSize: 11 }}>
                  uvicorn main:app --reload
                </code>
              </p>
            </div>
          ) : (
            <>
              {/* Stats row */}
              <div style={{ display: 'flex', gap: 10, marginBottom: 14 }}>
                <StatCard icon={<Share2 size={14} />} label="Nodes" value={result.num_nodes} accent={accent} />
                <StatCard icon={<GitBranch size={14} />} label="Edges" value={result.num_edges} accent={accent} />
              </div>

              {/* DAG status */}
              <div style={{
                background: isDAG ? '#0d2b1f' : '#2b1a0d',
                border: `1px solid ${isDAG ? '#34d39933' : '#fb923c33'}`,
                borderRadius: 8,
                padding: '10px 14px',
                display: 'flex', alignItems: 'flex-start', gap: 10,
              }}>
                {isDAG
                  ? <CheckCircle size={15} color="#34d399" style={{ flexShrink: 0, marginTop: 1 }} />
                  : <XCircle    size={15} color="#fb923c" style={{ flexShrink: 0, marginTop: 1 }} />
                }
                <div>
                  <p style={{ color: isDAG ? '#34d399' : '#fb923c', fontWeight: 700, fontSize: 12, margin: '0 0 2px' }}>
                    {isDAG ? 'Valid DAG' : 'Cycle Detected'}
                  </p>
                  <p style={{ color: '#8888a8', fontSize: 11, lineHeight: 1.5, margin: 0 }}>
                    {isDAG
                      ? 'No cycles found. This pipeline can be executed safely.'
                      : 'The pipeline contains a cycle and cannot be executed as-is.'}
                  </p>
                </div>
              </div>
            </>
          )}
        </div>

        {/* Footer */}
        <div style={{
          padding: '10px 18px 14px',
          display: 'flex', justifyContent: 'flex-end',
        }}>
          <button
            onClick={onClose}
            style={{
              background: '#1e1e2a',
              border: '1px solid #2a2a3a',
              borderRadius: 7,
              color: '#e8e8f0',
              fontSize: 12,
              fontWeight: 600,
              padding: '7px 18px',
              cursor: 'pointer',
              fontFamily: "'Inter', system-ui, sans-serif",
              transition: 'background 0.15s',
            }}
            onMouseEnter={e => e.currentTarget.style.background = '#2a2a3a'}
            onMouseLeave={e => e.currentTarget.style.background = '#1e1e2a'}
          >
            Close
          </button>
        </div>
      </div>

      <style>{`
        @keyframes modalIn {
          from { opacity: 0; transform: scale(0.95) translateY(8px); }
          to   { opacity: 1; transform: scale(1)    translateY(0);   }
        }
      `}</style>
    </div>
  );
};

const StatCard = ({ icon, label, value, accent }) => (
  <div style={{
    flex: 1,
    background: '#0a0a0f',
    border: '1px solid #2a2a3a',
    borderRadius: 8,
    padding: '10px 12px',
    display: 'flex', flexDirection: 'column', gap: 4,
  }}>
    <div style={{ display: 'flex', alignItems: 'center', gap: 5, color: '#55556a' }}>
      {icon}
      <span style={{ fontSize: 10, fontWeight: 600, letterSpacing: 0.5, textTransform: 'uppercase' }}>{label}</span>
    </div>
    <span style={{ fontSize: 24, fontWeight: 700, color: '#e8e8f0', lineHeight: 1 }}>{value}</span>
  </div>
);

/* ── Submit Button ── */
export const SubmitButton = () => {
  const { nodes, edges } = useStore(selector, shallow);
  const [loading, setLoading] = useState(false);
  const [result,  setResult]  = useState(null);
  const [error,   setError]   = useState(null);

  const handleSubmit = async () => {
    setLoading(true);
    setResult(null);
    setError(null);
    try {
      const res = await fetch('http://localhost:8000/pipelines/parse', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ nodes, edges }),
      });
      if (!res.ok) throw new Error(`Server error: ${res.status}`);
      const data = await res.json();
      setResult(data);
    } catch (err) {
      setError(`Could not reach backend.\n\n${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <ResultModal
        result={result}
        error={error}
        onClose={() => { setResult(null); setError(null); }}
      />

      <div style={{
        height: 52,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        background: '#111118',
        borderTop: '1px solid #1e1e2a',
        flexShrink: 0,
      }}>
        <button
          onClick={handleSubmit}
          disabled={loading}
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: 7,
            background: loading ? '#4346a8' : '#6366f1',
            color: '#fff',
            border: 'none',
            borderRadius: 7,
            padding: '8px 22px',
            fontSize: 13,
            fontWeight: 600,
            cursor: loading ? 'not-allowed' : 'pointer',
            letterSpacing: 0.2,
            fontFamily: "'Inter', system-ui, sans-serif",
            transition: 'background 0.15s, box-shadow 0.15s',
            boxShadow: '0 2px 12px #6366f140',
            opacity: loading ? 0.75 : 1,
          }}
          onMouseEnter={e => { if (!loading) { e.currentTarget.style.background = '#4f52d9'; e.currentTarget.style.boxShadow = '0 4px 20px #6366f160'; } }}
          onMouseLeave={e => { if (!loading) { e.currentTarget.style.background = '#6366f1'; e.currentTarget.style.boxShadow = '0 2px 12px #6366f140'; } }}
        >
          {loading
            ? <span style={{ width: 13, height: 13, border: '2px solid #ffffff60', borderTop: '2px solid #fff', borderRadius: '50%', display: 'inline-block', animation: 'spin 0.7s linear infinite' }} />
            : <Play size={13} strokeWidth={2.5} />
          }
          {loading ? 'Analyzing…' : 'Submit Pipeline'}
        </button>
      </div>

      <style>{`
        @keyframes spin { to { transform: rotate(360deg); } }
      `}</style>
    </>
  );
};
